-- The access pattern dictates the storage choice, not the schema.
-- This table is natural in a row store: narrow, point-addressed, mutated one row at a time.
CREATE TABLE orders (
  id         BIGINT PRIMARY KEY,
  user_id    BIGINT NOT NULL,
  status     SMALLINT NOT NULL,
  total_cents INTEGER NOT NULL,
  updated_at TIMESTAMPTZ NOT NULL
);
CREATE INDEX ON orders (user_id, updated_at);

-- Cheap in a row store: one B-tree probe + one heap fetch.
SELECT * FROM orders WHERE id = $1;

-- Expensive in a row store: reads every heap page to touch one column.
SELECT sum(total_cents) FROM orders WHERE updated_at > now() - interval '90 days';
